"use strict";(globalThis.webpackChunktesting_knowledge_base=globalThis.webpackChunktesting_knowledge_base||[]).push([[849],{6164(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"jmeterSidebar":[{"type":"category","label":"Apache JMeter","collapsible":false,"items":[{"type":"category","label":"Basics","collapsible":false,"items":[{"type":"link","href":"/docs/jmeter/01-install-tools","label":"Install Tools","docId":"jmeter/01-install-tools","unlisted":false},{"type":"link","href":"/docs/jmeter/02-understand-requirements","label":"Understand Requirements and Flow","docId":"jmeter/02-understand-requirements","unlisted":false},{"type":"link","href":"/docs/jmeter/03-jmeter-elements","label":"JMeter Elements Overview","docId":"jmeter/03-jmeter-elements","unlisted":false},{"type":"category","label":"Recording","collapsed":false,"items":[{"type":"link","href":"/docs/jmeter/04-recording","label":"Recording with BlazeMeter + Fiddler","docId":"jmeter/04-recording","unlisted":false},{"type":"link","href":"/docs/jmeter/04a-recording-mitmproxy","label":"Recording with BlazeMeter + mitmproxy","docId":"jmeter/04a-recording-mitmproxy","unlisted":false}],"collapsible":true},{"type":"link","href":"/docs/jmeter/05-correlation-parameterization","label":"Correlation and Parameterization","docId":"jmeter/05-correlation-parameterization","unlisted":false},{"type":"link","href":"/docs/jmeter/06-script-enhancement","label":"Script Enhancement","docId":"jmeter/06-script-enhancement","unlisted":false},{"type":"link","href":"/docs/jmeter/07-debug","label":"Debug","docId":"jmeter/07-debug","unlisted":false}],"collapsed":false},{"type":"category","label":"Applying Load","collapsible":false,"items":[{"type":"link","href":"/docs/jmeter/08-load-model","label":"Design Load Model","docId":"jmeter/08-load-model","unlisted":false},{"type":"link","href":"/docs/jmeter/09-execute-analyze","label":"Execute and Analyze Results","docId":"jmeter/09-execute-analyze","unlisted":false},{"type":"link","href":"/docs/jmeter/10-reporting","label":"Reporting","docId":"jmeter/10-reporting","unlisted":false}],"collapsed":false},{"type":"category","label":"Advanced","collapsible":false,"items":[{"type":"link","href":"/docs/jmeter/11-backend-listener","label":"Backend Listener - InfluxDB + Grafana","docId":"jmeter/11-backend-listener","unlisted":false},{"type":"link","href":"/docs/jmeter/12-distributed-testing","label":"Distributed Testing","docId":"jmeter/12-distributed-testing","unlisted":false},{"type":"link","href":"/docs/jmeter/13-distributed-testing-hands-on","label":"Try Distributed Testing on Your Own Machine","docId":"jmeter/13-distributed-testing-hands-on","unlisted":false},{"type":"link","href":"/docs/jmeter/14-test-data-python","label":"Test Data Preparation with Python","docId":"jmeter/14-test-data-python","unlisted":false},{"type":"link","href":"/docs/jmeter/15-automation-batch","label":"Automation with Batch Files","docId":"jmeter/15-automation-batch","unlisted":false}],"collapsed":false},{"type":"category","label":"Appendix","collapsible":false,"items":[{"type":"link","href":"/docs/jmeter/99-future-to-explore","label":"Future / To Explore","docId":"jmeter/99-future-to-explore","unlisted":false},{"type":"link","href":"/docs/jmeter/99-archive-oci-linux-slave-setup","label":"OCI Linux Slave Setup (Archived)","docId":"jmeter/99-archive-oci-linux-slave-setup","unlisted":false}],"collapsed":false}],"collapsed":false,"href":"/docs/jmeter/"}]},"docs":{"jmeter/01-install-tools":{"id":"jmeter/01-install-tools","title":"Install Tools","description":"Before starting performance testing, you need the following tools set up on your machine.","sidebar":"jmeterSidebar"},"jmeter/02-understand-requirements":{"id":"jmeter/02-understand-requirements","title":"Understand Requirements and Flow","description":"Before opening JMeter, you need to understand what you are testing and why. Skipping this step leads to wasted effort - building scripts for the wrong flows or testing with unrealistic numbers.","sidebar":"jmeterSidebar"},"jmeter/03-jmeter-elements":{"id":"jmeter/03-jmeter-elements","title":"JMeter Elements Overview","description":"Before you start recording and building scripts, you need to understand the building blocks of JMeter. This section covers the elements you\'ll use most often and how they relate to each other.","sidebar":"jmeterSidebar"},"jmeter/04-recording":{"id":"jmeter/04-recording","title":"Recording with BlazeMeter + Fiddler","description":"This section covers how to record your test script using both Fiddler and Blazemeter simultaneously. This dual-recording approach gives you the best of both tools.","sidebar":"jmeterSidebar"},"jmeter/04a-recording-mitmproxy":{"id":"jmeter/04a-recording-mitmproxy","title":"Recording with BlazeMeter + mitmproxy","description":"This page is the dual recording workflow with mitmproxy in place of Fiddler Classic. It works on macOS and Windows. The only change is the evidence-capture tool. BlazeMeter stays exactly as it is in Section 4 - Recording.","sidebar":"jmeterSidebar"},"jmeter/05-correlation-parameterization":{"id":"jmeter/05-correlation-parameterization","title":"Correlation and Parameterization","description":"After recording, the script has hardcoded values everywhere - tokens, session IDs, timestamps, and other dynamic values that change every session. The script will fail on replay if these are not handled. This step makes the script dynamic.","sidebar":"jmeterSidebar"},"jmeter/06-script-enhancement":{"id":"jmeter/06-script-enhancement","title":"Script Enhancement","description":"After correlation and parameterization, the script works but it\'s messy - auto-generated names, flat structure, no validation. This step turns it into a clean, maintainable, and robust test plan.","sidebar":"jmeterSidebar"},"jmeter/07-debug":{"id":"jmeter/07-debug","title":"Debug","description":"After enhancing the script with transaction controllers, assertions, extractors, and timers, you need to verify it actually works end-to-end before running any load. Debugging is about running the script with a single user and making sure every request succeeds, every extraction works, and every assertion passes.","sidebar":"jmeterSidebar"},"jmeter/08-load-model":{"id":"jmeter/08-load-model","title":"Design Load Model","description":"The script works with 1 user - now you need to define how to apply load. The load model determines how many users, how fast they ramp up, how long the test runs, and what the pacing looks like. All of this comes from the requirements gathered in Section 2.","sidebar":"jmeterSidebar"},"jmeter/09-execute-analyze":{"id":"jmeter/09-execute-analyze","title":"Execute and Analyze Results","description":"The script is debugged, the load model is defined - now it\'s time to run the actual load test and make sense of the results. Always run load tests in CLI mode (command line), never from the GUI.","sidebar":"jmeterSidebar"},"jmeter/10-reporting":{"id":"jmeter/10-reporting","title":"Reporting","description":"You have the results - now you need to communicate them. The report should be clear enough for both technical and non-technical stakeholders to understand whether the system passed or failed.","sidebar":"jmeterSidebar"},"jmeter/11-backend-listener":{"id":"jmeter/11-backend-listener","title":"Backend Listener - InfluxDB + Grafana","description":"The JMeter web report is generated after the test finishes. If you want to monitor results in real-time while the test is running, you need a Backend Listener that streams data to InfluxDB, which Grafana then visualizes as a live dashboard.","sidebar":"jmeterSidebar"},"jmeter/12-distributed-testing":{"id":"jmeter/12-distributed-testing","title":"Distributed Testing","description":"When a single machine can\'t generate enough load (CPU or memory maxes out before reaching the target thread count), you distribute the load across multiple machines. JMeter has built-in support for this using a controller-worker architecture.","sidebar":"jmeterSidebar"},"jmeter/13-distributed-testing-hands-on":{"id":"jmeter/13-distributed-testing-hands-on","title":"Try Distributed Testing on Your Own Machine","description":"Section 12 covers the theory of distributed testing - controller, workers, RMI, and the many things that can go wrong between them. This section is where you actually do it, end to end, on hardware you already own.","sidebar":"jmeterSidebar"},"jmeter/14-test-data-python":{"id":"jmeter/14-test-data-python","title":"Test Data Preparation with Python","description":"When running distributed tests with unique data per user, you need to split CSV files so each worker machine gets a different subset. Python makes this quick and repeatable.","sidebar":"jmeterSidebar"},"jmeter/15-automation-batch":{"id":"jmeter/15-automation-batch","title":"Automation with Batch Files","description":"Manually starting jmeter-server on each worker, copying files, and running the test gets repetitive fast - especially when you have multiple machines and run tests frequently. Batch files automate these steps.","sidebar":"jmeterSidebar"},"jmeter/99-archive-oci-linux-slave-setup":{"id":"jmeter/99-archive-oci-linux-slave-setup","title":"OCI Linux Slave Setup (Archived)","description":"Archived: This guide is kept for reference, not as the recommended path. To learn distributed testing hands-on, use Try Distributed Testing on Your Own Machine instead - it teaches the same workflow with free local VMs and no cloud account. Come back here when you specifically need Oracle Cloud, and be aware the OCI console and free-tier terms may have changed since this was written.","sidebar":"jmeterSidebar"},"jmeter/99-future-to-explore":{"id":"jmeter/99-future-to-explore","title":"Future / To Explore","description":"Topics not covered in this guide but worth exploring as you advance.","sidebar":"jmeterSidebar"},"jmeter/index":{"id":"jmeter/index","title":"Performance Testing with JMeter","description":"A practical guide on how to approach performance testing using JMeter \u2014 from setup to automation.","sidebar":"jmeterSidebar"}}}}')}}]);